ns.guideText = {
  ["forever.druid"] = "Leather, three forms and a mana bar that does not work in two of them. Wrath, Healing Touch and Mark of the Wild are yours from the start, Moonfire and Rejuvenation come at 4, Thorns at 6 and Entangling Roots at 8. At 10 you get Bear Form, Maul and your first talent point, and Cat Form follows at 20. Every line below says which form to be in before it says what to press.",
  ["forever.druid-balance.dry"] = "A caster that is meleeing has already run out of mana.",
  ["forever.druid-balance.intro"] = "Balance casts Wrath and Starfire from range, keeps Moonfire and Insect Swarm on the monster, and shifts into Moonkin Form at 40. Eclipse makes Wrath speed up the Starfires after it. It is slow before Hurricane at 40 and every kill costs mana, so guides level as Feral and come here later.",
  ["forever.druid-balance.line"] = "Wrath, Starfire, Moonfire and Insect Swarm from range. Slow alone, with Moonkin Form at 40.",
  ["forever.druid-balance.note"] = "(41 points in Balance, 10 in Restoration for Heart of the Wild, Reflection and Naturalist.)",
  ["forever.druid-balance.p1"] = "Wrath casts faster and costs less mana. It is the spell you cast most until 20, and wow.gg puts it first.",
  ["forever.druid-balance.p10"] = "The fifth rank of Genesis, now that Eclipse is taken. Method wants all five.",
  ["forever.druid-balance.p11"] = "A spell crit makes your next casts faster for a short time. Warcraft Tavern lists it among the Balance talents.",
  ["forever.druid-balance.p12"] = "Arcane and Nature spells hit harder. Wrath, Starfire and Moonfire all count.",
  ["forever.druid-balance.p13"] = "Raises your armour and your party's crit chance, but you cannot heal in it. Warcraft Tavern names it as the tree's milestone at 40.",
  ["forever.druid-balance.p14"] = "Starfire casts faster and can stun the monster. Eclipse speeds it up again, so this is the second half of that pair.",
  ["forever.druid-balance.p15"] = "More Intellect, which is more mana and more crit. It is the gate to Reflection and Naturalist, which Method names for casters.",
  ["forever.druid-balance.p16"] = "Part of your mana regeneration keeps going while you cast. A caster runs out of mana before monsters, and this is the fix.",
  ["forever.druid-balance.p17"] = "Your Arcane and Nature spells crit for more. Crits are where Starfire's damage is.",
  ["forever.druid-balance.p18"] = "All the damage you deal rises with each rank, and Healing Touch casts faster. Two ranks are what the last points allow.",
  ["forever.druid-balance.p2"] = "Your damage spells cost less mana. Every kill costs mana, and this is the cheapest way to make it last.",
  ["forever.druid-balance.p3"] = "Your Balance spells reach further and miss less. A longer reach means you cast for longer before the monster arrives.",
  ["forever.druid-balance.p4"] = "Moonfire hits harder and crits more. You put it on every monster, and it is the gate to Vengeance.",
  ["forever.druid-balance.p5"] = "A little more crit chance with spells and melee attacks. Method names it, and it is the gate to Nature's Splendor.",
  ["forever.druid-balance.p6"] = "Moonfire lasts longer, and so do Rejuvenation, Regrowth and Insect Swarm. A longer Moonfire is damage you pay for once.",
  ["forever.druid-balance.p7"] = "A second damage over time that also lowers the monster's chance to hit you. Method and Warcraft Tavern both put it at 25.",
  ["forever.druid-balance.p8"] = "Your damage over time does more with each rank. Moonfire and Insect Swarm are both over time. Method wants all five.",
  ["forever.druid-balance.p9"] = "Wrath makes your next Starfires cast faster. Cast Wrath, then Starfire, and the pair is quicker than either alone.",
  ["forever.druid-balance.s1"] = "Before your first talent point. The same kit in every build. Wrath and Moonfire from range do the killing, Healing Touch and Rejuvenation keep you up, and Bear Form and your first talent point come at 10.",
  ["forever.druid-balance.s1.between1.if"] = "after a fight, if you are hurt, from 4",
  ["forever.druid-balance.s1.between1.why"] = "it heals while you drink",
  ["forever.druid-balance.s1.between2.if"] = "when it has run out",
