  ["forever.druid-feral-cat.s1.opening2.if"] = "before each pull, from 6",
  ["forever.druid-feral-cat.s1.opening2.why"] = "it hurts every monster that hits you",
  ["forever.druid-feral-cat.s1.opening3.if"] = "to pull, from as far as it reaches",
  ["forever.druid-feral-cat.s1.opening3.why"] = "the monster spends its walk taking damage",
  ["forever.druid-feral-cat.s1.opening4.if"] = "right after it, from 4",
  ["forever.druid-feral-cat.s1.opening4.why"] = "it burns at once and keeps burning",
  ["forever.druid-feral-cat.s1.rarely1.if"] = "when a second monster joins, from 8",
  ["forever.druid-feral-cat.s1.rarely1.why"] = "it holds one still while you finish the first",
  ["forever.druid-feral-cat.s2"] = "Cat Form is ten levels away, so you fight as a bear. Maul and Swipe are your damage, Enrage gives you Rage to start, and Demoralizing Roar softens a pack. Claw, Rip and Shred come at 20, and your first points go to Ferocity.",
  ["forever.druid-feral-cat.s2.between1.if"] = "after a fight, if you are hurt",
