  ["forever.druid-feral-cat.s3"] = "Cat Form comes at 20 with Claw, Rip and Shred, Rake and Ferocious Bite at 24, Ravage at 32 and Pounce at 36. Prowl first and open from behind. Bear Form stays for a pack, and a monster you would rather not fight as a cat.",
  ["forever.druid-feral-cat.s3.between1.if"] = "after a fight, if you are hurt",
  ["forever.druid-feral-cat.s3.between1.why"] = "it heals while you drink",
  ["forever.druid-feral-cat.s3.between2.if"] = "when it has run out",
