  ["forever.druid-feral-cat.s3.between3.why"] = "each shift costs a large part of your mana",
  ["forever.druid-feral-cat.s3.loop1.if"] = "with 4 or 5 combo points, on a monster that lives",
  ["forever.druid-feral-cat.s3.loop1.why"] = "it is your best finisher",
  ["forever.druid-feral-cat.s3.loop2.if"] = "at 5 combo points, when it will die",
  ["forever.druid-feral-cat.s3.loop2.why"] = "it finishes at once",
  ["forever.druid-feral-cat.s3.loop3.if"] = "when it is not bleeding, from 24",
  ["forever.druid-feral-cat.s3.loop3.why"] = "it bleeds for you and gives a combo point",
  ["forever.druid-feral-cat.s3.loop4.if"] = "when you are behind it",
  ["forever.druid-feral-cat.s3.loop4.why"] = "it hits hard and gives a combo point",
  ["forever.druid-feral-cat.s3.loop5.why"] = "it works from any side and gives a combo point",
  ["forever.druid-feral-cat.s3.low1.if"] = "when you cannot afford an attack",
  ["forever.druid-feral-cat.s3.low1.text"] = "Let your Energy fill",
  ["forever.druid-feral-cat.s3.low1.why"] = "it comes back on its own, so waiting costs nothing",
  ["forever.druid-feral-cat.s3.low2.if"] = "before you shift into a form again",
  ["forever.druid-feral-cat.s3.low2.text"] = "Sit and drink",
  ["forever.druid-feral-cat.s3.low2.why"] = "each shift costs a large part of your mana",
  ["forever.druid-feral-cat.s3.opening1.if"] = "before you pull",
  ["forever.druid-feral-cat.s3.opening1.why"] = "every cat attack needs it",
  ["forever.druid-feral-cat.s3.opening2.if"] = "when the monster has not seen you",
  ["forever.druid-feral-cat.s3.opening2.why"] = "Ravage and Pounce can only be used from it",
  ["forever.druid-feral-cat.s3.opening3.if"] = "from behind, from 32",
  ["forever.druid-feral-cat.s3.opening3.why"] = "it is your hardest opener",
  ["forever.druid-feral-cat.s3.opening4.if"] = "from behind, until you have Ravage",
  ["forever.druid-feral-cat.s3.opening4.why"] = "it is the hardest hit you have there",
  ["forever.druid-feral-cat.s3.opening5.if"] = "when you are seen",
  ["forever.druid-feral-cat.s3.opening5.why"] = "its armour drops, so every hit lands harder",
  ["forever.druid-feral-cat.s3.rarely1.if"] = "when you need to get behind a monster",
  ["forever.druid-feral-cat.s3.rarely1.why"] = "it leaps you behind it, so Shred works",
  ["forever.druid-feral-cat.s3.rarely2.if"] = "against three or more monsters",
  ["forever.druid-feral-cat.s3.rarely2.why"] = "Swipe hits them all, and a bear is hard to kill",
  ["forever.druid-feral-cat.s3.rarely3.if"] = "in a group, when a monster turns on you, from 28",
  ["forever.druid-feral-cat.s3.rarely3.why"] = "it lowers your threat",
  ["forever.druid-feral-cat.s3.rarely4.if"] = "to reach a monster or to run, from 26",
  ["forever.druid-feral-cat.s3.rarely4.why"] = "it makes you faster without breaking Prowl",
  ["forever.druid-feral-cat.s4"] = "Dire Bear Form and Innervate come at 40, Barkskin at 44, and Shifting Power with your thirty-first point. Open from Prowl, keep Rake and Rip on the monster, and let Shifting Power refill the Energy when it runs dry.",
  ["forever.druid-feral-cat.s4.between1.if"] = "after a fight, if you are hurt",
  ["forever.druid-feral-cat.s4.between1.why"] = "it heals while you drink",
  ["forever.druid-feral-cat.s4.between2.if"] = "when it has run out",
  ["forever.druid-feral-cat.s4.between2.why"] = "armour for an hour is cheap",
  ["forever.druid-feral-cat.s4.between3.if"] = "after a fight, before you shift back",
  ["forever.druid-feral-cat.s4.between3.text"] = "Sit and drink",
  ["forever.druid-feral-cat.s4.between3.why"] = "each shift costs a large part of your mana",
  ["forever.druid-feral-cat.s4.big"] = "Innervate on yourself when your mana runs low, Barkskin when a fight goes wrong",
  ["forever.druid-feral-cat.s4.loop1.if"] = "when your Energy is nearly gone",
  ["forever.druid-feral-cat.s4.loop1.why"] = "it turns mana into Energy at once",
  ["forever.druid-feral-cat.s4.loop2.if"] = "with 4 or 5 combo points, on a monster that lives",
  ["forever.druid-feral-cat.s4.loop2.why"] = "it is your best finisher",
  ["forever.druid-feral-cat.s4.loop3.if"] = "at 5 combo points, when it will die",
  ["forever.druid-feral-cat.s4.loop3.why"] = "it finishes at once",
  ["forever.druid-feral-cat.s4.loop4.if"] = "when it is not bleeding",
  ["forever.druid-feral-cat.s4.loop4.why"] = "it bleeds for you and gives a combo point",
  ["forever.druid-feral-cat.s4.loop5.if"] = "when you are behind it",
  ["forever.druid-feral-cat.s4.loop5.why"] = "it hits hard and gives a combo point",
  ["forever.druid-feral-cat.s4.loop6.why"] = "it works from any side and gives a combo point",
  ["forever.druid-feral-cat.s4.low1.if"] = "when you cannot afford an attack",
  ["forever.druid-feral-cat.s4.low1.text"] = "Let your Energy fill",
  ["forever.druid-feral-cat.s4.low1.why"] = "it comes back on its own, so waiting costs nothing",
  ["forever.druid-feral-cat.s4.low2.if"] = "before you shift into a form again",
  ["forever.druid-feral-cat.s4.low2.text"] = "Sit and drink",
  ["forever.druid-feral-cat.s4.low2.why"] = "each shift costs a large part of your mana",
  ["forever.druid-feral-cat.s4.opening1.if"] = "before you pull",
  ["forever.druid-feral-cat.s4.opening1.why"] = "every cat attack needs it",
  ["forever.druid-feral-cat.s4.opening2.if"] = "when the monster has not seen you",
  ["forever.druid-feral-cat.s4.opening2.why"] = "Ravage and Pounce can only be used from it",
  ["forever.druid-feral-cat.s4.opening3.if"] = "from behind",
  ["forever.druid-feral-cat.s4.opening3.why"] = "it is your hardest opener",
  ["forever.druid-feral-cat.s4.opening4.if"] = "when you are seen",
  ["forever.druid-feral-cat.s4.opening4.why"] = "its armour drops, so every hit lands harder",
  ["forever.druid-feral-cat.s4.rarely1.if"] = "from Prowl, when you want a stun",
  ["forever.druid-feral-cat.s4.rarely1.why"] = "it stuns and bleeds the monster",
  ["forever.druid-feral-cat.s4.rarely2.if"] = "against three or more monsters",
  ["forever.druid-feral-cat.s4.rarely2.why"] = "Swipe hits them all, and a bear is hard to kill",
  ["forever.druid-feral-cat.s4.rarely3.if"] = "in a group, when a monster turns on you",
  ["forever.druid-feral-cat.s4.rarely3.why"] = "it lowers your threat",
  ["forever.druid-feral-cat.s4.rarely4.if"] = "to reach a monster or to run",
  ["forever.druid-feral-cat.s4.rarely4.why"] = "it makes you faster without breaking Prowl",
  ["forever.druid-feral-cat.split"] = "the points after 40 and Shifting Power. Mobalytics ends with a Balance tail and the last 20 points here follow it, with Natural Shapeshifter in place of Nature's Reach, which helps spells only. Method takes Shifting Power and Mobalytics skips it. Nobody has played past 30.",
  ["forever.druid-feral-cat.variant"] = "cat",
  ["forever.druid-restoration.dry"] = "A heal that lands after the tank has died heals no one.",
  ["forever.druid-restoration.intro"] = "Restoration keeps a group alive with heals over time: Rejuvenation and Regrowth on the tank, Swiftmend when it drops, Wild Growth at 40. Guides do not level it alone, so this page is for dungeons and says what to do in between. You cannot heal in a form, so you step out of one to do it.",
  ["forever.druid-restoration.line"] = "Rejuvenation, Regrowth and Swiftmend on a group. Guides do not level it alone.",
  ["forever.druid-restoration.note"] = "(51 points in Restoration, every talent of the tree.)",
  ["forever.druid-restoration.p1"] = "A hit is less likely to delay your cast. A healer is hit while healing, so wow.gg's healing page takes it first.",
  ["forever.druid-restoration.p10"] = "Every healing spell you cast heals a little more with each rank.",
  ["forever.druid-restoration.p11"] = "Regrowth crits more often. Regrowth is the heal for a tank who is falling behind.",
  ["forever.druid-restoration.p12"] = "A heal over time on a target and its party, with a long cast. Maxroll saves it for emergencies because it costs a lot of mana.",
  ["forever.druid-restoration.p13"] = "More Intellect, which is more mana, and more Stamina in Bear Form for the times you shift.",
  ["forever.druid-restoration.p14"] = "Healing Touch and Tranquility cost less mana. You cast Healing Touch a lot, and mana is what ends a dungeon.",
  ["forever.druid-restoration.p15"] = "When Rejuvenation or Regrowth runs out, the target is healed for as much as your Spirit. No guide has played it, so this is what the talent says.",
  ["forever.druid-restoration.p16"] = "Every healing spell you cast heals a little more with each rank.",
  ["forever.druid-restoration.p17"] = "Tranquility makes no threat and comes back sooner. It is a party heal you can use more than once in a hard fight.",
  ["forever.druid-restoration.p18"] = "Your Nature and Arcane spells make less threat. A heal that pulls the monster onto you is a heal that goes wrong.",
  ["forever.druid-restoration.p19"] = "Shifting costs less mana. You shift to travel or to fight alone, then back to heal.",
  ["forever.druid-restoration.p2"] = "Healing Touch casts faster, and all your damage rises. It is the gate to Nature's Swiftness at 30, and wow.gg takes it second.",
  ["forever.druid-restoration.p3"] = "Part of your mana regeneration keeps going while you cast. A healer casts all the time, and Mobalytics calls it great sustain.",
  ["forever.druid-restoration.p4"] = "Every healing spell you cast heals a little more with each rank.",
  ["forever.druid-restoration.p5"] = "Heals at once a target that has your Rejuvenation or Regrowth on it. It is your emergency button, and the guides list it at 25.",
  ["forever.druid-restoration.p6"] = "Rejuvenation heals more, and it is the gate to Improved Regrowth. Rejuvenation is the heal you keep on the tank.",
  ["forever.druid-restoration.p7"] = "Every healing spell you cast heals a little more with each rank.",
  ["forever.druid-restoration.p8"] = "Your next Nature spell is instant. Use it on Healing Touch when the tank is about to die.",
  ["forever.druid-restoration.p9"] = "More Spirit, so more mana regeneration. It is the gate to Wild Growth at 40.",
  ["forever.druid-restoration.s1"] = "Before your first talent point. The same kit in every build. Wrath and Moonfire from range do the killing, Healing Touch and Rejuvenation keep you up, and Bear Form and your first talent point come at 10.",
  ["forever.druid-restoration.s1.between1.if"] = "after a fight, if you are hurt, from 4",
  ["forever.druid-restoration.s1.between1.why"] = "it heals while you drink",
  ["forever.druid-restoration.s1.between2.if"] = "when it has run out",
  ["forever.druid-restoration.s1.between2.why"] = "armour for an hour is cheap",
  ["forever.druid-restoration.s1.between3.if"] = "after a fight, before the next pull",
  ["forever.druid-restoration.s1.between3.text"] = "Sit and drink",
  ["forever.druid-restoration.s1.between3.why"] = "mana from drinking is cheap, and a pull on empty is not",
  ["forever.druid-restoration.s1.loop1.if"] = "when your health is low",
  ["forever.druid-restoration.s1.loop1.why"] = "a heal costs less than a death",
  ["forever.druid-restoration.s1.loop2.if"] = "on a monster that will live a while",
  ["forever.druid-restoration.s1.loop2.why"] = "it keeps hurting it while you cast Wrath",
  ["forever.druid-restoration.s1.loop3.if"] = "while you have mana",
  ["forever.druid-restoration.s1.loop3.why"] = "it is your main attack",
  ["forever.druid-restoration.s1.loop4.why"] = "a swing costs no mana, so use it when the mana is gone",
  ["forever.druid-restoration.s1.low1.if"] = "when your mana is nearly gone",
  ["forever.druid-restoration.s1.low1.why"] = "a swing costs no mana",
  ["forever.druid-restoration.s1.low2.if"] = "after a fight, before the next pull",
  ["forever.druid-restoration.s1.low2.text"] = "Sit and drink",
  ["forever.druid-restoration.s1.low2.why"] = "mana from drinking is cheap, and a pull on empty is not",
  ["forever.druid-restoration.s1.opening1.if"] = "before the first pull",
  ["forever.druid-restoration.s1.opening1.why"] = "it raises your armour for an hour",
  ["forever.druid-restoration.s1.opening2.if"] = "before each pull, from 6",
  ["forever.druid-restoration.s1.opening2.why"] = "it hurts every monster that hits you",
  ["forever.druid-restoration.s1.opening3.if"] = "to pull, from as far as it reaches",
  ["forever.druid-restoration.s1.opening3.why"] = "the monster spends its walk taking damage",
  ["forever.druid-restoration.s1.opening4.if"] = "right after it, from 4",
  ["forever.druid-restoration.s1.opening4.why"] = "it burns at once and keeps burning",
  ["forever.druid-restoration.s1.rarely1.if"] = "when a second monster joins, from 8",
  ["forever.druid-restoration.s1.rarely1.why"] = "it holds one still while you finish the first",
  ["forever.druid-restoration.s2"] = "Alone, Wrath and Moonfire still do the killing and Rejuvenation keeps you up. In a group, Rejuvenation on the tank before the pull, Regrowth when it falls behind, Healing Touch for a big hit. Regrowth and Revive come at 12 and Cure Poison at 14.",
  ["forever.druid-restoration.s2.between1.if"] = "after a fight, if you are hurt",
  ["forever.druid-restoration.s2.between1.why"] = "it heals while you drink",
  ["forever.druid-restoration.s2.between2.if"] = "when it has run out",
  ["forever.druid-restoration.s2.between2.why"] = "armour for an hour is cheap",
  ["forever.druid-restoration.s2.between3.if"] = "after a fight, before the next pull",
  ["forever.druid-restoration.s2.between3.text"] = "Sit and drink",
  ["forever.druid-restoration.s2.between3.why"] = "mana from drinking is cheap, and a pull on empty is not",
  ["forever.druid-restoration.s2.loop1.if"] = "when the tank is falling behind, from 12",
  ["forever.druid-restoration.s2.loop1.why"] = "it heals now and keeps healing",
  ["forever.druid-restoration.s2.loop2.if"] = "for a big hit",
  ["forever.druid-restoration.s2.loop2.why"] = "it is the biggest heal you have",
  ["forever.druid-restoration.s2.loop3.if"] = "when it has run out on the tank",
  ["forever.druid-restoration.s2.loop3.why"] = "it is the cheapest heal you have",
  ["forever.druid-restoration.s2.loop4.if"] = "alone, or with spare mana",
  ["forever.druid-restoration.s2.loop4.why"] = "it keeps hurting while you cast",
  ["forever.druid-restoration.s2.loop5.why"] = "spare mana is better spent on damage than lost",
  ["forever.druid-restoration.s2.low1.if"] = "when your mana is nearly gone",
  ["forever.druid-restoration.s2.low1.text"] = "Heal only the tank",
  ["forever.druid-restoration.s2.low1.why"] = "one heal that lands beats three you cannot afford",
  ["forever.druid-restoration.s2.low2.if"] = "after a fight, before the next pull",
  ["forever.druid-restoration.s2.low2.text"] = "Sit and drink",
  ["forever.druid-restoration.s2.low2.why"] = "mana from drinking is cheap, and a pull on empty is not",
  ["forever.druid-restoration.s2.opening1.if"] = "before the first pull",
  ["forever.druid-restoration.s2.opening1.why"] = "it raises your armour for an hour",
  ["forever.druid-restoration.s2.opening2.if"] = "on the tank, before each pull",
  ["forever.druid-restoration.s2.opening2.why"] = "it hurts every monster that hits them",
  ["forever.druid-restoration.s2.opening3.if"] = "on the tank, before the pull",
  ["forever.druid-restoration.s2.opening3.why"] = "it heals before the first hit lands",
  ["forever.druid-restoration.s2.opening4.if"] = "alone, to pull",
  ["forever.druid-restoration.s2.opening4.why"] = "it burns at once and keeps burning",
  ["forever.druid-restoration.s2.rarely1.if"] = "when a poison is on someone, from 14",
  ["forever.druid-restoration.s2.rarely1.why"] = "it takes the poison off",
  ["forever.druid-restoration.s2.rarely2.if"] = "out of a fight, on a dead player, from 12",
  ["forever.druid-restoration.s2.rarely2.why"] = "it brings them back before you move on",
  ["forever.druid-restoration.s2.rarely3.if"] = "alone, when a second monster joins",
  ["forever.druid-restoration.s2.rarely3.why"] = "it holds one still while you finish the first",
  ["forever.druid-restoration.s3"] = "Rebirth comes at 20, Swiftmend with your sixteenth point at 25, and Nature's Swiftness and Tranquility at 30. Keep Rejuvenation on the tank, Swiftmend a target that is dropping, and spend Regrowth and Healing Touch on what Rejuvenation cannot hold.",
  ["forever.druid-restoration.s3.between1.if"] = "after a fight, if you are hurt",
  ["forever.druid-restoration.s3.between1.why"] = "it heals while you drink",
  ["forever.druid-restoration.s3.between2.if"] = "out of a fight, on a dead player",
  ["forever.druid-restoration.s3.between2.why"] = "it brings them back before you move on",
  ["forever.druid-restoration.s3.between3.if"] = "when it has run out",
  ["forever.druid-restoration.s3.between3.why"] = "armour for an hour is cheap",
  ["forever.druid-restoration.s3.between4.if"] = "after a fight, before the next pull",
  ["forever.druid-restoration.s3.between4.text"] = "Sit and drink",
  ["forever.druid-restoration.s3.between4.why"] = "mana from drinking is cheap, and a pull on empty is not",
  ["forever.druid-restoration.s3.big"] = "Nature's Swiftness when someone is about to die, Tranquility when all are hurt",
  ["forever.druid-restoration.s3.loop1.if"] = "when someone is about to die",
  ["forever.druid-restoration.s3.loop1.say"] = "then cast Healing Touch",
  ["forever.druid-restoration.s3.loop1.why"] = "your next heal is instant",
  ["forever.druid-restoration.s3.loop2.if"] = "when a target with your heal on it is dropping",
  ["forever.druid-restoration.s3.loop2.why"] = "it heals at once, from the heal already there",
  ["forever.druid-restoration.s3.loop3.if"] = "when the tank is falling behind",
  ["forever.druid-restoration.s3.loop3.why"] = "it heals now and keeps healing",
  ["forever.druid-restoration.s3.loop4.if"] = "for a big hit",
  ["forever.druid-restoration.s3.loop4.why"] = "it is the biggest heal you have",
  ["forever.druid-restoration.s3.loop5.if"] = "when it has run out on the tank",
  ["forever.druid-restoration.s3.loop5.why"] = "it is the cheapest heal you have",
  ["forever.druid-restoration.s3.loop6.why"] = "spare mana is better spent on damage than lost",
  ["forever.druid-restoration.s3.low1.if"] = "when your mana is nearly gone",
  ["forever.druid-restoration.s3.low1.text"] = "Heal only the tank",
