  ["forever.hunter-marksmanship.s1.opening3.say"] = "stand still so it fires",
  ["forever.hunter-marksmanship.s1.opening3.why"] = "the pull is free and the monster walks to you",
  ["forever.hunter-marksmanship.s1.opening4.if"] = "on a monster that will live a while",
  ["forever.hunter-marksmanship.s1.opening4.why"] = "it burns while you shoot",
  ["forever.hunter-marksmanship.s2"] = "Your pet quest is at 10: tame a boar, call it out and keep it fed. Marksmanship puts the damage in your own shots, so stay at range and let the pet hold the monster. Aspect of the Hawk replaces the Monkey once it does.",
  ["forever.hunter-marksmanship.s2.between1.if"] = "once the class quest teaches it",
  ["forever.hunter-marksmanship.s2.between1.why"] = "a boar holds threat, takes hits and eats anything",
  ["forever.hunter-marksmanship.s2.between2.if"] = "after a fight, if the pet is hurt",
  ["forever.hunter-marksmanship.s2.between2.why"] = "it heals your pet while you focus",
