  ["forever.mage-arcane.s1.opening3.if"] = "from as far away as it reaches",
  ["forever.mage-arcane.s1.opening3.why"] = "the monster spends its walk taking damage",
  ["forever.mage-arcane.s2"] = "Frost Nova arrives at 10, Arcane Explosion at 14. Missile Barrage turns your casts into free Arcane Missiles.",
