  ["forever.paladin-retribution.s4.loop2.why"] = "it is a weapon strike with Holy damage added",
  ["forever.paladin-retribution.s4.loop3.if"] = "when it is at 20% health or less",
  ["forever.paladin-retribution.s4.loop3.why"] = "it only works on a monster that is nearly dead",
  ["forever.paladin-retribution.s4.loop4.if"] = "in a long fight, with Unsealed Wrath",
  ["forever.paladin-retribution.s4.loop4.text"] = "Change seal",
  ["forever.paladin-retribution.s4.loop4.why"] = "the stored copies of the old seal fire on the new one",
