  ["forever.priest-shadow.s1.opening3.why"] = "the monster spends its walk taking damage",
  ["forever.priest-shadow.s2"] = "Mind Blast comes at 10 and Inner Fire at 12. Shield yourself, pull with Mind Blast, add Pain and let the wand finish. Spirit Tap gives the mana back after kills.",
