  ["forever.rogue-assassination.s4"] = "Mutilate at 42 is the build. Daggers, a poison on each, Shank on cooldown. Slice and Dice gets stronger at 42.",
  ["forever.rogue-assassination.s4.between1.if"] = "when the coating is gone",
  ["forever.rogue-assassination.s4.between1.text"] = "Coat both weapons in poison",
  ["forever.rogue-assassination.s4.between1.why"] = "each hit may poison, and it costs no Energy",
