  ["forever.rogue-assassination.s4.between2.why"] = "Energy comes back by itself, health does not",
  ["forever.rogue-assassination.s4.big"] = "before the Eviscerate or Mutilate that matters most",
  ["forever.rogue-assassination.s4.loop1.if"] = "when it is ready and Energy is not full",
