  ["forever.rogue-subtlety.s4"] = "Death Mark at 42 stores your damage and deals it at once. Shank adds combo points through Boot Knife. Slice and Dice gets stronger at 42.",
  ["forever.rogue-subtlety.s4.between1.if"] = "when the coating is gone",
  ["forever.rogue-subtlety.s4.between1.text"] = "Coat both weapons in poison",
  ["forever.rogue-subtlety.s4.between1.why"] = "each hit may poison, and it costs no Energy",
  ["forever.rogue-subtlety.s4.between2.if"] = "after a fight, before the next pull",
  ["forever.rogue-subtlety.s4.between2.text"] = "Bandage or eat",
  ["forever.rogue-subtlety.s4.between2.why"] = "Energy comes back by itself, health does not",
  ["forever.rogue-subtlety.s4.loop1.if"] = "when it is ready",
  ["forever.rogue-subtlety.s4.loop1.why"] = "you dodge more, and Garrote needs no Stealth",
  ["forever.rogue-subtlety.s4.loop2.if"] = "when it is ready and Energy is not full",
  ["forever.rogue-subtlety.s4.loop2.why"] = "it gives back more Energy than it costs",
  ["forever.rogue-subtlety.s4.loop3.if"] = "when it has run out",
  ["forever.rogue-subtlety.s4.loop3.why"] = "your swings come faster for the whole fight",
  ["forever.rogue-subtlety.s4.loop4.if"] = "at 4 or 5 points, on a long fight",
  ["forever.rogue-subtlety.s4.loop4.why"] = "it deals the damage it stored a moment later",
  ["forever.rogue-subtlety.s4.loop5.if"] = "at 5 combo points, near the end of the fight",
  ["forever.rogue-subtlety.s4.loop5.why"] = "it spends the points on one big hit",
  ["forever.rogue-subtlety.s4.loop6.why"] = "it builds points with any weapon, from any side",
