  ["forever.shaman-restoration.s3.low1.if"] = "when the group is low on mana",
  ["forever.shaman-restoration.s3.low1.why"] = "it gives the whole group mana back",
  ["forever.shaman-restoration.s3.opening1.if"] = "if you took it, before each pull",
  ["forever.shaman-restoration.s3.opening1.why"] = "it gives back mana when you are hit or crit",
  ["forever.shaman-restoration.s3.opening2.if"] = "if you did not take Water Shield",
  ["forever.shaman-restoration.s3.opening2.why"] = "its orbs hurt whatever hits you",
  ["forever.shaman-restoration.s3.opening3.if"] = "when your group needs the mana",
  ["forever.shaman-restoration.s3.opening3.why"] = "it gives mana back to you and your party",
  ["forever.shaman-restoration.s3.opening4.if"] = "on the tank, before the pull",
  ["forever.shaman-restoration.s3.opening4.why"] = "a heal that lands early beats a bigger one that lands late",
  ["forever.shaman-restoration.s3.rarely1.if"] = "when a fear is coming",
  ["forever.shaman-restoration.s3.rarely1.why"] = "it breaks fear, charm and sleep",
  ["forever.shaman-restoration.s3.rarely2.if"] = "for steady light damage",
  ["forever.shaman-restoration.s3.rarely2.why"] = "it heals a little all the time",
  ["forever.shaman-restoration.s3.rarely3.if"] = "to travel, out of a fight",
  ["forever.shaman-restoration.s3.rarely3.why"] = "it is faster than walking, and you cannot cast in it",
  ["forever.shaman-restoration.s4"] = "Riptide and Chain Heal at 40 are your group healing: put Riptide on the hurt, then Chain Heal that target. Healing Way and Purification make every heal count. Keep your group close so Chain Heal can jump.",
  ["forever.shaman-restoration.s4.between1.if"] = "after a fight, before the next pull",
  ["forever.shaman-restoration.s4.between1.text"] = "Sit and drink",
  ["forever.shaman-restoration.s4.between1.why"] = "mana from drinking is cheap, and a pull on empty is not",
  ["forever.shaman-restoration.s4.between2.if"] = "when you leave your totems behind",
  ["forever.shaman-restoration.s4.between2.why"] = "it gives back part of their mana",
  ["forever.shaman-restoration.s4.big"] = "Swiftness for an emergency heal, Mana Tide when the group runs low",
  ["forever.shaman-restoration.s4.loop1.if"] = "on a hurt ally who does not have it",
  ["forever.shaman-restoration.s4.loop1.why"] = "it heals over time and powers up Chain Heal",
  ["forever.shaman-restoration.s4.loop2.if"] = "when two or more are hurt",
  ["forever.shaman-restoration.s4.loop2.why"] = "it jumps on, and hits harder on a Riptide target",
  ["forever.shaman-restoration.s4.loop3.if"] = "when a big hit would land too late",
  ["forever.shaman-restoration.s4.loop3.why"] = "it is quicker than Healing Wave but heals less for its mana",
  ["forever.shaman-restoration.s4.loop4.if"] = "on whoever is hurt worst",
  ["forever.shaman-restoration.s4.loop4.why"] = "it is your efficient heal",
  ["forever.shaman-restoration.s4.loop5.if"] = "against a dangerous cast",
  ["forever.shaman-restoration.s4.loop5.why"] = "it stops the cast before you must heal it",
  ["forever.shaman-restoration.s4.loop6.why"] = "damage from range while the group is healthy",
  ["forever.shaman-restoration.s4.low1.if"] = "when the group is low on mana",
  ["forever.shaman-restoration.s4.low1.why"] = "it gives the whole group mana back",
  ["forever.shaman-restoration.s4.opening1.if"] = "if you took it, before each pull",
  ["forever.shaman-restoration.s4.opening1.why"] = "it gives back mana when you are hit or crit",
  ["forever.shaman-restoration.s4.opening2.if"] = "if you did not take Water Shield",
  ["forever.shaman-restoration.s4.opening2.why"] = "its orbs hurt whatever hits you",
  ["forever.shaman-restoration.s4.opening3.if"] = "when your group needs the mana",
  ["forever.shaman-restoration.s4.opening3.why"] = "it gives mana back to you and your party",
  ["forever.shaman-restoration.s4.opening4.if"] = "on the tank, before the pull",
  ["forever.shaman-restoration.s4.opening4.why"] = "it heals over time and powers up Chain Heal",
  ["forever.shaman-restoration.s4.rarely1.if"] = "when a fear is coming",
  ["forever.shaman-restoration.s4.rarely1.why"] = "it breaks fear, charm and sleep",
