  ["forever.warlock-demonology.s1.opening3.why"] = "it burns while the monster walks to you",
  ["forever.warlock-demonology.s2"] = "Your Voidwalker quest is at 10. It holds the monster while you cast, and Unholy Power makes it hit harder. Corruption casts faster with its first point.",
