  ["mage-frost.s4.between3.why"] = "eating brings health back for no mana",
  ["mage-frost.s4.big"] = "Ice Block for the worst fight, Cold Snap for a second one",
  ["mage-frost.s4.loop1.if"] = "if a monster is casting a spell",
  ["mage-frost.s4.loop1.why"] = "it stops that school of spells for a while",
  ["mage-frost.s4.loop2.if"] = "if it has gone and the monster hits you",
  ["mage-frost.s4.loop2.why"] = "it shields you, and hits do not interrupt spells",
  ["mage-frost.s4.loop3.if"] = "if the monster reaches you",
  ["mage-frost.s4.loop3.why"] = "it freezes it, and you step back to cast",
  ["mage-frost.s4.loop4.if"] = "if the monster is frozen",
  ["mage-frost.s4.loop4.why"] = "spells crit far more often against a frozen monster",
  ["mage-frost.s4.loop5.if"] = "if the monster is nearly dead",
  ["mage-frost.s4.loop5.why"] = "with a wand equipped, it costs no mana and your bar refills",
  ["mage-frost.s4.loop6.why"] = "it is your main bolt, and it slows the monster",
  ["mage-frost.s4.low1.if"] = "if mana, not health, runs out first",
  ["mage-frost.s4.low1.why"] = "it keeps part of your mana regeneration while you cast",
  ["mage-frost.s4.low2.if"] = "when the bar is nearly empty",
  ["mage-frost.s4.low2.why"] = "with a wand equipped, it costs no mana",
  ["mage-frost.s4.low3.if"] = "when the fight is over and the bar is empty",
